const lead = $('Um lead por vez').first().json;

const primeiroNome = String(lead.nome || '').replace(/\s+/g, ' ').trim().split(' ')[0] || '';
const tentativasFeitas = Number(lead.tentativas || 0);
const etapa = String(lead.etapa || '');

// Frase de reserva por etapa. Só é usada se a IA não responder ou
// devolver algo que não dá pra usar.
const reservaPorEtapa = {
  novo: 'as informações do seu caso',
  potencial: 'as informações do seu caso',
  qualificado: 'as informações do seu caso',
  calculo: 'a estimativa do seu caso',
  acompanhamento: 'a análise do seu caso',
  sem_laudo: 'o documento que pedi'
};
const reserva = reservaPorEtapa[etapa] || 'as informações do seu caso';

// Pega o trecho que a IA escreveu
let trecho = '';
try {
  trecho = String($('Escreve o trecho do contexto').first().json.text || '').trim();
} catch (e) {
  trecho = '';
}

// Limpa aspas e pontuação que a IA possa ter colocado nas pontas
trecho = trecho.replace(/^["'`\s]+/, '').replace(/["'`.!?\s]+$/, '').trim();

// Se veio vazio, com quebra de linha, ou longo demais, usa a reserva.
// Isso garante que uma falha da IA nunca trava nem estraga a mensagem.
const quantidadePalavras = trecho ? trecho.split(/\s+/).length : 0;
if (!trecho || trecho.indexOf('\n') !== -1 || quantidadePalavras > 12) {
  trecho = reserva;
}

// As três frases são fixas — só o trecho muda. Português correto, com acentos.
// Nenhuma chama o lead pelo nome: o nome em leads_crm pode ser o nome de
// exibição do WhatsApp, não necessariamente o nome real.
let texto = '';

if (tentativasFeitas === 0) {
  texto = 'Oi! Está por aí ainda? Só pra confirmar se posso seguir com ' + trecho + '.';
} else if (tentativasFeitas === 1) {
  texto = 'Oi, aqui é da equipe Monteiro Ramalho. Fique à vontade pra responder quando estiver num lugar mais tranquilo — só fica pendente ' + trecho + ' pra eu continuar seu atendimento.';
} else {
  texto = 'Você está online? Preciso só confirmar ' + trecho + ' pra continuar seu atendimento.';
}

const memoriaAgente = JSON.stringify({
  type: 'ai',
  data: {
    content: texto,
    tool_calls: [],
    invalid_tool_calls: [],
    additional_kwargs: {},
    response_metadata: {}
  }
});

const corpo = {
  messaging_product: 'whatsapp',
  to: String(lead.telefone),
  type: 'text',
  text: { body: texto }
};

return [{
  json: {
    lead_id: lead.id,
    telefone: String(lead.telefone),
    nome: primeiroNome,
    etapa: etapa,
    numero_da_tentativa: tentativasFeitas + 1,
    trecho_usado: trecho,
    veio_da_ia: trecho !== reserva,
    mensagem_completa: texto,
    memoria_agente: memoriaAgente,
    corpo: corpo
  }
}];

// Guard do retorno combinado (lembrete manual do CRM).
// Marca cada candidato desta cobranca. Quem tem retorno combinado aberto
// (agendado, processando, enviado ou incerto) nao recebe cobranca.
// O item segue intacto: so ganha o campo guard_retorno_combinado.
// Itens sem id (ex.: resposta vazia do banco) seguem como antes.
const lista = $('Leads com retorno combinado aberto').first().json.retornos_abertos_por_lead;
if (lista === null || lista === undefined || typeof lista !== 'object' || Array.isArray(lista)) {
  throw new Error('Guard do retorno combinado: lista de retornos abertos invalida. Nenhuma cobranca enviada nesta execucao.');
}
return $input.all().map((item, i) => {
  const id = item.json && item.json.id != null ? String(item.json.id) : null;
  const status = id ? lista[id] : undefined;
  let decisao = 'liberado';
  if (status) {
    decisao = String(status).includes('incerto') ? 'retorno_incerto_revisao_humana' : 'retorno_combinado_aberto';
  }
  return { json: { ...item.json, guard_retorno_combinado: decisao }, pairedItem: { item: i } };
});
